function shiftDistance(s, t, nextCost, previousCost) {
  const nextSum = new Array(53).fill(0);
  const prevSum = new Array(53).fill(0);
  for (let i = 0; i < 52; i++) {
    nextSum[i + 1] = nextSum[i] + nextCost[i % 26];
    prevSum[i + 1] = prevSum[i] + previousCost[i % 26];
  }

  let total = 0;
  for (let i = 0; i < s.length; i++) {
    const from = s.charCodeAt(i) - 97;
    const to = t.charCodeAt(i) - 97;
    const forwardEnd = to < from ? to + 26 : to;
    const forward = nextSum[forwardEnd] - nextSum[from];
    const backwardStart = from < to ? from + 26 : from;
    const backward = prevSum[backwardStart + 1] - prevSum[to + 1];
    total += Math.min(forward, backward);
  }
  return total;
}

