function shiftDistance(s, t, nextCost, previousCost) {
  // Floyd-Warshall over the 26 letters, with one edge per allowed single step.
  const dist = Array.from({ length: 26 }, (_, a) => Array.from({ length: 26 }, (_, b) => (a === b ? 0 : Infinity)));
  for (let a = 0; a < 26; a++) {
    const up = (a + 1) % 26, down = (a + 25) % 26;
    dist[a][up] = Math.min(dist[a][up], nextCost[a]);
    dist[a][down] = Math.min(dist[a][down], previousCost[a]);
  }
  for (let k = 0; k < 26; k++)
    for (let a = 0; a < 26; a++)
      for (let b = 0; b < 26; b++)
        if (dist[a][k] + dist[k][b] < dist[a][b]) dist[a][b] = dist[a][k] + dist[k][b];
  let sum = 0;
  for (let i = 0; i < s.length; i++) sum += dist[s.charCodeAt(i) - 97][t.charCodeAt(i) - 97];
  return sum;
}

