function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const large = size === 'large';
  const n = large ? 10000 : 1 + pick(8);
  // Small inputs draw letters from a random window of the alphabet so equal letters and wraps both happen.
  const span = large ? 26 : 1 + pick(26);
  const low = pick(27 - span);
  const word = () => Array.from({ length: n }, () => String.fromCharCode(97 + low + pick(span))).join('');
  const top = large ? 1e9 : [0, 1, 9, 100, 1e9][pick(5)];
  const costs = () => Array.from({ length: 26 }, () => pick(top + 1));
  return [word(), word(), costs(), costs()];
}
